import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

// spec: specs/hal-engine-config-hooks/spec.md#7
it('passes a failed beforeSession to onError and afterSession before rethrowing', async () => {
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const failure = new Error('setup failed');
  const calls: unknown[][] = [];
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      calls.push(['provider']);
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
    hooks: {
      beforeSession: async received => {
        calls.push(['beforeSession', received]);
        throw failure;
      },
      onError: async (received, error) => {
        calls.push(['onError', received, error]);
      },
      afterSession: async received => {
        calls.push(['afterSession', received]);
      },
    },
  });

  const rejectedWith = await orchestrator.processMessage(session).catch(error => error);

  expect({rejectedWith, calls}).toEqual({
    rejectedWith: failure,
    calls: [
      ['beforeSession', session],
      ['onError', session, failure],
      ['afterSession', session],
    ],
  });
});

